package com.multi2.app.engine

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.io.File
import java.security.SecureRandom

/**
 * Virtual device identity per (space, app) — parity with the original's
 * "Device virtual ID" set: android id, wifi mac, bluetooth mac, icc serial.
 * Generated on install, regenerated by the GENERATE_ID engine task,
 * shown/reset on the Device Info screen, spoofed to guests where hookable.
 */
@Serializable
data class VirtualDeviceInfo(
    val androidId: String,
    val wifiMac: String,
    val bluetoothMac: String,
    val iccSerial: String,
) {
    companion object {
        private val random = SecureRandom()

        fun generate(): VirtualDeviceInfo {
            val hex = { len: Int ->
                ByteArray(len).also { random.nextBytes(it) }
                    .joinToString("") { "%02x".format(it) }
            }
            val mac = {
                // locally administered unicast (02:xx:xx:xx:xx:xx)
                val b = ByteArray(6).also { random.nextBytes(it) }
                b[0] = 0x02
                b.joinToString(":") { "%02X".format(it) }
            }
            val icc = buildString {
                append("89") // telecom industry prefix
                repeat(18) { append(random.nextInt(10)) }
            }
            return VirtualDeviceInfo(
                androidId = hex(8),
                wifiMac = mac(),
                bluetoothMac = mac(),
                iccSerial = icc,
            )
        }
    }
}

object VirtualDeviceStore {

    private val json = Json { ignoreUnknownKeys = true }

    private fun file(context: Context, spaceId: Int, pkg: String): File =
        File(EnginePaths.dataDir(context, spaceId, pkg), "virtual_device.json")

    fun load(context: Context, spaceId: Int, pkg: String): VirtualDeviceInfo? {
        val f = file(context, spaceId, pkg)
        if (!f.exists()) return null
        return runCatching { json.decodeFromString<VirtualDeviceInfo>(f.readText()) }.getOrNull()
    }

    fun loadOrGenerate(context: Context, spaceId: Int, pkg: String): VirtualDeviceInfo {
        load(context, spaceId, pkg)?.let { return it }
        return regenerate(context, spaceId, pkg)
    }

    fun regenerate(context: Context, spaceId: Int, pkg: String): VirtualDeviceInfo {
        val info = VirtualDeviceInfo.generate()
        val f = file(context, spaceId, pkg)
        f.parentFile?.mkdirs()
        f.writeText(json.encodeToString(VirtualDeviceInfo.serializer(), info))
        return info
    }
}
